import{_ as n,C as d,o as e,c as i,a2 as a,b as l,w as o,a as s,E as h,a3 as c}from"./chunks/framework.DToEn73J.js";const g=JSON.parse('{"title":"Context Window 管理","description":"","frontmatter":{"title":"Context Window 管理","chapter":"3.2","order":2,"summary":"通过 token 预算分配、滑动窗口裁剪与中间结果摘要压缩（compaction），在固定 Context Window 下维持长任务可用性。"},"headers":[],"relativePath":"03-context-memory/context-window.md","filePath":"03-context-memory/context-window.md","lastUpdated":1788254264000}'),E={name:"03-context-memory/context-window.md"};function m(A,t,p,_,u,x){const r=d("Mermaid");return e(),i("div",null,[t[1]||(t[1]=a('<h1 id="context-window-管理" tabindex="-1">Context Window 管理 <a class="header-anchor" href="#context-window-管理" aria-label="Permalink to &quot;Context Window 管理&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>Context Window 管理是在模型上下文长度有硬上限的前提下，对 system、history、tool results 做预算划分与动态裁剪，避免长程 Agent Loop 因溢出而失败或退化。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><p><strong>Token 预算分配</strong>（按优先级预留，以 200k 窗口为例）：</p><table tabindex="0"><thead><tr><th>区块</th><th>预算占比</th><th>策略</th></tr></thead><tbody><tr><td>System prompt</td><td>10%</td><td>固定，极少变动</td></tr><tr><td>当前 Plan/Task</td><td>15%</td><td>完整保留</td></tr><tr><td>工具结果</td><td>45%</td><td>超阈值截断</td></tr><tr><td>历史对话</td><td>25%</td><td>可裁剪/摘要</td></tr><tr><td>余量</td><td>5%</td><td>防溢出</td></tr></tbody></table><p><strong>滑动窗口</strong>：保留最近 N 轮，更早的轮次移出窗口。</p><p><strong>中间结果摘要压缩（compaction）</strong>：对移出窗口的内容，用模型生成结构化摘要回写 Memory，后续以摘要形式重新注入，而非丢弃。</p>',8)),(e(),l(c,null,{default:o(()=>[h(r,{id:"mermaid-93",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E6%96%B0%E6%B6%88%E6%81%AF%5D%20--%3E%20B%7B%E8%B6%85%E5%87%BA%E9%A2%84%E7%AE%97%3F%7D%0A%20%20%20%20B%20--%20%E5%90%A6%20--%3E%20C%5B%E7%9B%B4%E6%8E%A5%E5%85%A5%E7%AA%97%5D%0A%20%20%20%20B%20--%20%E6%98%AF%20--%3E%20D%5B%E8%A3%81%E5%89%AA%E6%9C%80%E6%97%A7%E8%BD%AE%E6%AC%A1%5D%0A%20%20%20%20D%20--%3E%20E%5B%E8%B0%83%E7%94%A8%E6%A8%A1%E5%9E%8B%E7%94%9F%E6%88%90%E6%91%98%E8%A6%81%5D%0A%20%20%20%20E%20--%3E%20F%5B%E6%91%98%E8%A6%81%E5%86%99%E5%85%A5%20Session%2FMemory%5D%0A%20%20%20%20F%20--%3E%20G%5B%E6%91%98%E8%A6%81%E6%9B%BF%E4%BB%A3%E5%8E%9F%E6%96%87%E5%9B%9E%E6%B3%A8%5D%0A%20%20%20%20G%20--%3E%20C%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<p><strong>何时触发压缩</strong>：窗口使用率 &gt; 85%、单条工具结果 &gt; 8k token、或轮次超过窗口承载阈值。</p><h2 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h2><p>不做裁剪与压缩，长任务会在数十轮后触发上下文截断（模型“失忆”）、或被迫重启丢失进度。预算与压缩是长程任务能否跑完的物理前提。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>等到真正溢出才裁剪，导致当轮工具调用已丢关键信息。</li><li>摘要无结构化 schema，回注后模型无法可靠解析。</li></ul><h2 id="业界实现对照" tabindex="-1">业界实现对照 <a class="header-anchor" href="#业界实现对照" aria-label="Permalink to &quot;业界实现对照&quot;">​</a></h2><ul><li>LangGraph：用 <code>memory</code> + 自定义 reducer 实现消息裁剪与状态压缩（<a href="https://langchain-ai.github.io/langgraph/concepts/low_level/#reducers" target="_blank" rel="noreferrer">docs</a>）。</li><li>mem0：异步存储并压缩交互记忆，减轻主上下文压力（<a href="https://docs.mem0.ai/" target="_blank" rel="noreferrer">docs</a>）。</li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/fk-ai-agent/03-context-memory/context-engineering">上下文工程</a></li><li><a href="/fk-ai-agent/03-context-memory/session-state">会话状态与恢复</a></li><li><a href="/fk-ai-agent/01-agent-basics/budget-control">预算控制</a></li><li><a href="/fk-ai-agent/03-context-memory/long-term-memory">长期记忆选型</a></li></ul><hr><p><em>最后核实日期：2026-08-26</em></p>',11))])}const B=n(E,[["render",m]]);export{g as __pageData,B as default};
